class P { n!: number; s!: string; set(n: number): void { this.n = n; } }
function h(p: P): number { return p.n }
const ar = (p: P): number => p.n;
const ar2 = (p: P): number => { return p.n; };
function touch(p: P): number { p.n = 5; return p.n; }
function main(): void {
  const p = new P();
  console.log(h(p), ar(p), ar2(p));
  const arr: number[] = [];
  arr.push(p.n);
  console.log(arr);
  const m = new Map<string, number>();
  m.set("k", p.n);
  console.log(m);
  console.log({ n: p.n });
  const o = { n: p.n, s: p.s };
  console.log(o);
  const ps = [new P(), new P()];
  ps[0].set(3);
  const mapped = ps.map(x => x.n);
  console.log(mapped);
  console.log(Math.max(...mapped));
  console.log(Math.max(...ps.map(x => x.n)));
  const v = p.n;
  console.log(v);
  let w: number = p.n;
  console.log(w, typeof w);
  const z = [p.n, 1];
  console.log(z);
  const q = new P();
  console.log(touch(q), q.n);
  q.set(9);
  console.log(h(q), q);
}
